const D=[
{id:"beshbarmak",n:"Beshbarmak (Kazakh Meat and Noodles)",c:"Kazakhstan",f:"🇰🇿",m:95,x:["lamb","flat noodles","onion","beef broth","black pepper","parsley"],q:[[160,"g"],[100,"g"],[70,"g"],[350,"ml"],[0.25,"tsp"],[5,"g"]],s:["Simmer the lamb gently in broth until tender, skimming the surface as needed.","Lift out the meat, slice it, and keep it warm under a little broth.","Cook broad flat noodles in the strained broth and soften sliced onion in a separate ladleful.","Layer noodles, lamb, and onion on a platter; spoon over broth and finish with pepper and parsley."],co:"#7c6743",source:"https://en.wikipedia.org/wiki/Beshbarmak",license:LICENSE,sourceNote:NOTE},
{id:"chakalaka",n:"Chakalaka (South African Spicy Vegetable Relish)",c:"South Africa",f:"🇿🇦",m:35,x:["canned beans","tomato","onion","carrot","bell pepper","curry powder"],q:[[120,"g"],[120,"g"],[60,"g"],[70,"g"],[80,"g"],[1,"tsp"]],s:["Soften chopped onion and bell pepper in a lightly oiled pan.","Add grated carrot and curry powder and cook until fragrant.","Stir in tomato and simmer until thick but still textured.","Fold in drained beans, heat through, and adjust the seasoning before serving warm or cool."],co:"#c25b32",source:"https://www.epicurious.com/recipes/food/views/chakalaka-spicy-vegetable-relish",license:LICENSE,sourceNote:NOTE},
{id:"chorba-frik",n:"Chorba Frik (Algerian Green-Wheat Soup)",c:"Algeria",f:"🇩🇿",m:55,x:["lamb","green wheat","tomato","chickpeas","celery","cilantro"],q:[[100,"g"],[45,"g"],[120,"g"],[70,"g"],[40,"g"],[8,"g"]],s:["Brown the diced lamb, then add chopped celery and tomato and cook until softened.","Pour in 450 ml water, cover, and simmer until the lamb is nearly tender.","Add rinsed green wheat and cooked chickpeas and simmer until the grain thickens the soup.","Season, stir in chopped cilantro, and serve piping hot."],co:"#a94734",source:"https://en.wikipedia.org/wiki/Chorba_frik",license:LICENSE,sourceNote:NOTE},
{id:"lahmacun",n:"Lahmacun (Turkish Spiced Meat Flatbread)",c:"Turkey",f:"🇹🇷",m:50,x:["flatbread dough","ground beef","tomato","onion","parsley","paprika"],q:[[120,"g"],[90,"g"],[80,"g"],[40,"g"],[8,"g"],[1,"tsp"]],s:["Heat the oven and an inverted baking tray to 240°C.","Finely chop tomato, onion, and parsley and mix with ground beef, paprika, salt, and pepper.","Roll the dough paper-thin and spread the meat mixture in a very thin, even layer.","Bake on the hot tray until the base is crisp and the topping is cooked; fold and serve."],co:"#ba4b33",source:"https://en.wikipedia.org/wiki/Lahmacun",license:LICENSE,sourceNote:NOTE},
{id:"pabellon-criollo",n:"Pabellón Criollo (Venezuelan Beef, Beans and Rice)",c:"Venezuela",f:"🇻🇪",m:65,x:["beef","black beans","rice","plantain","tomato","onion"],q:[[130,"g"],[100,"g"],[70,"g"],[100,"g"],[100,"g"],[60,"g"]],s:["Simmer the beef until tender enough to shred, reserving a little cooking liquid.","Cook onion and tomato, add the shredded beef, and simmer until juicy.","Warm the black beans and cook the rice separately until tender.","Pan-fry ripe plantain slices and arrange all four components side by side."],co:"#d2a53c",source:"https://www.recetasnestle.cl/la-cocina-nestle/coccion-y-tecnica/pabellon-criollo",license:LICENSE,sourceNote:NOTE},
{id:"ropa-vieja",n:"Ropa Vieja (Cuban Shredded Beef Stew)",c:"Cuba",f:"🇨🇺",m:100,x:["beef","tomato","onion","bell pepper","olive","cumin"],q:[[160,"g"],[120,"g"],[60,"g"],[80,"g"],[25,"g"],[1,"tsp"]],s:["Braise the beef in water until fork-tender, then cool slightly and shred it.","Soften sliced onion and bell pepper, then add tomato and cumin.","Return the beef with a little braising liquid and simmer until the sauce clings to the strands.","Stir in sliced olives, check the seasoning, and serve with rice."],co:"#b84f3e",source:"https://latino.si.edu/learn/latino-history-and-culture/latino-culture/latino-food",license:LICENSE,sourceNote:NOTE},
{id:"hainanese-chicken-rice",n:"Hainanese Chicken Rice (Singapore Poached Chicken Rice)",c:"Singapore",f:"🇸🇬",m:55,x:["chicken","rice","chicken broth","ginger","garlic","pandan leaves"],q:[[160,"g"],[80,"g"],[350,"ml"],[10,"g"],[1,"piece"],[1,"piece"]],s:["Poach the chicken gently in broth with sliced ginger until fully cooked, then rest it covered.","Lightly fry rinsed rice with minced garlic and a little chicken fat or oil.","Cook the rice with measured poaching broth and a knotted pandan leaf.","Slice the chicken and serve it over the fragrant rice with a spoonful of hot broth."],co:"#d9a64b",source:"https://www.sg101.gov.sg/resources/archives/heritage-hainanese-chicken-rice-in-singapore/",license:LICENSE,sourceNote:NOTE},
{id:"ful-medames",n:"Ful Medames (Egyptian Seasoned Fava Beans)",c:"Egypt",f:"🇪🇬",m:20,x:["fava beans","lemon","garlic","cumin","olive oil","tomato"],q:[[180,"g"],[0.5,"piece"],[1,"piece"],[0.5,"tsp"],[1,"tbsp"],[80,"g"]],s:["Warm the cooked fava beans with a few spoonfuls of water until very soft.","Mash about half the beans, leaving the rest whole for texture.","Mix in crushed garlic, cumin, lemon juice, and olive oil.","Top with diced tomato, adjust salt and acidity, and serve warm."],co:"#a2763e",source:"https://link.springer.com/article/10.1186/s42779-020-00073-1",license:LICENSE,sourceNote:NOTE},
{id:"kutia",n:"Kutia (Ukrainian Wheat, Poppy Seed and Honey Pudding)",c:"Ukraine",f:"🇺🇦",m:75,x:["wheat berries","poppy seeds","honey","walnut","raisins","water"],q:[[70,"g"],[15,"g"],[1,"tbsp"],[20,"g"],[20,"g"],[300,"ml"]],s:["Simmer soaked wheat berries in fresh water until tender but still pleasantly chewy.","Soak the poppy seeds in hot water, drain, and grind until aromatic.","Drain the wheat and mix it with poppy seeds, honey, chopped walnuts, and raisins.","Loosen with a little warm water, rest for the flavors to combine, and serve warm or chilled."],co:"#78614f",source:"https://en.wikipedia.org/wiki/Kutia",license:LICENSE,sourceNote:NOTE},
{id:"soto-betawi",n:"Soto Betawi (Jakarta Beef and Coconut Soup)",c:"Indonesia",f:"🇮🇩",m:75,x:["beef","coconut milk","potato","tomato","ginger","lime"],q:[[140,"g"],[150,"ml"],[120,"g"],[80,"g"],[8,"g"],[0.5,"piece"]],s:["Simmer the beef with ginger in water until tender, then cut it into bite-size pieces.","Cook the potato separately until nearly tender and drain it.","Add coconut milk to the strained beef broth and heat gently without boiling hard.","Return beef and potato, add tomato, season, and finish each bowl with lime."],co:"#c98942",source:"https://en.wikipedia.org/wiki/Soto_Betawi",license:LICENSE,sourceNote:NOTE}
];
window.EXTRA_RECIPES=(window.EXTRA_RECIPES||[]).concat(D);
window.RECIPE_I18N=window.RECIPE_I18N||{};
Object.assign(window.RECIPE_I18N,{
"beshbarmak":{ko:["베슈바르마크(카자흐식 고기·넓은면)",["양고기를 육수에 부드러워질 때까지 약하게 삶으며 거품을 걷습니다.","고기를 건져 썰고 육수를 조금 끼얹어 따뜻하게 둡니다.","거른 육수에 넓은면을 삶고 다른 육수에 양파를 부드럽게 익힙니다.","면, 고기, 양파를 겹쳐 담고 육수와 후추, 파슬리를 더합니다."]],es:["Beshbarmak (carne kazaja con fideos anchos)",["Cuece el cordero suavemente en caldo hasta que esté tierno.","Retira, corta y mantén caliente con un poco de caldo.","Cuece los fideos en el caldo colado y ablanda la cebolla aparte.","Sirve fideos, carne y cebolla con caldo, pimienta y perejil."]],ja:["ベシュバルマク（カザフ風肉と幅広麺）",["ラムをスープで柔らかくなるまで静かに煮ます。","肉を取り出して切り、少量のスープで温めます。","こしたスープで幅広麺をゆで、別に玉ねぎを煮ます。","麺、肉、玉ねぎを盛り、スープとこしょう、パセリを加えます。"]],zh:["别什巴尔马克（哈萨克肉配宽面）",["羊肉放汤中小火煮软，及时撇沫。","捞出切片，淋少量汤保温。","过滤肉汤煮宽面，另取少量汤煮软洋葱。","依次铺面、肉和洋葱，浇汤并撒胡椒和欧芹。"]]},
"chakalaka":{ko:["차칼라카(남아프리카식 매콤 채소 렐리시)",["기름을 살짝 두른 팬에서 양파와 피망을 부드럽게 볶습니다.","간 당근과 카레가루를 넣어 향을 냅니다.","토마토를 넣어 형태가 조금 남도록 걸쭉하게 끓입니다.","물기 뺀 콩을 섞어 데우고 간을 맞춰 따뜻하거나 차게 냅니다."]],es:["Chakalaka (condimento sudafricano picante de verduras)",["Ablanda cebolla y pimiento en una sartén con poco aceite.","Añade zanahoria rallada y curry.","Agrega tomate y cuece hasta espesar conservando textura.","Incorpora frijoles, calienta, sazona y sirve tibio o frío."]],ja:["チャカラカ（南アフリカ風辛味野菜レリッシュ）",["少量の油で玉ねぎとピーマンを柔らかく炒めます。","にんじんとカレー粉を加え香りを出します。","トマトを加え、形を残して濃く煮ます。","水気を切った豆を混ぜて温め、味を調えます。"]],zh:["恰卡拉卡（南非香辣蔬菜佐酱）",["少油炒软洋葱和彩椒。","加入胡萝卜丝和咖喱粉炒香。","加入番茄，保持颗粒感煮至浓稠。","拌入沥干豆子加热，调味后冷热皆可。"]]},
"chorba-frik":{ko:["쇼르바 프리크(알제리식 풋밀 수프)",["깍둑 썬 양고기를 굽고 셀러리와 토마토를 넣어 부드럽게 볶습니다.","물 450ml를 붓고 덮어 고기가 거의 부드러워질 때까지 끓입니다.","씻은 풋밀과 익힌 병아리콩을 넣어 수프가 걸쭉해지도록 끓입니다.","간을 맞추고 다진 고수를 넣어 뜨겁게 냅니다."]],es:["Chorba frik (sopa argelina de trigo verde)",["Dora el cordero y ablanda apio y tomate.","Añade 450 ml de agua y cuece tapado hasta casi tierno.","Agrega trigo verde y garbanzos y cuece hasta espesar.","Sazona, añade cilantro y sirve muy caliente."]],ja:["ショルバ・フリーク（アルジェリア風青麦スープ）",["ラムを焼き、セロリとトマトを柔らかく炒めます。","水450mlを加え、肉がほぼ柔らかくなるまで煮ます。","青麦とひよこ豆を加え、とろみがつくまで煮ます。","味を調え、香菜を混ぜて熱々を出します。"]],zh:["绿麦羊肉汤（阿尔及利亚风味）",["羊肉丁煎香，加入芹菜和番茄炒软。","加450毫升水，盖盖煮至羊肉近软。","加入洗净绿麦和熟鹰嘴豆，煮至汤浓。","调味，拌香菜后趁热食用。"]]},
"lahmacun":{ko:["라흐마준(튀르키예식 향신 고기 납작빵)",["오븐과 뒤집은 팬을 240°C로 예열합니다.","토마토, 양파, 파슬리를 잘게 썰어 다진 쇠고기와 파프리카가루에 섞습니다.","반죽을 종이처럼 얇게 밀고 고기 혼합물을 얇고 고르게 폅니다.","밑면이 바삭하고 고기가 익을 때까지 뜨거운 팬에 구워 접어 냅니다."]],es:["Lahmacun (pan plano turco con carne especiada)",["Calienta horno y bandeja invertida a 240 °C.","Mezcla tomate, cebolla y perejil picados con carne y pimentón.","Estira la masa muy fina y extiende una capa fina de carne.","Hornea hasta que la base esté crujiente y la carne cocida."]],ja:["ラフマジュン（トルコ風スパイス肉の薄焼きパン）",["オーブンと裏返した天板を240℃に熱します。","トマト、玉ねぎ、パセリを刻み、牛ひき肉とパプリカに混ぜます。","生地を紙のように薄く伸ばし、肉だねを薄く広げます。","底がカリッとし肉に火が通るまで焼き、折って出します。"]],zh:["土耳其香料肉末薄饼（拉赫马俊）",["烤箱和倒扣烤盘预热至240°C。","番茄、洋葱和欧芹切碎，与牛肉末和红椒粉拌匀。","面团擀得极薄，均匀铺薄层肉馅。","放热烤盘烤至底脆肉熟，折叠食用。"]]},
"pabellon-criollo":{ko:["파베욘 크리오요(베네수엘라식 쇠고기·콩·밥 한상)",["쇠고기를 찢어질 만큼 부드럽게 삶고 육수를 조금 남깁니다.","양파와 토마토를 볶아 찢은 고기를 넣고 촉촉하게 조립니다.","검은콩을 데우고 쌀은 따로 부드럽게 익힙니다.","잘 익은 플랜틴을 팬에 굽고 네 가지 음식을 나란히 담습니다."]],es:["Pabellón criollo (carne, frijoles y arroz venezolanos)",["Cuece la carne hasta poder deshebrarla y reserva caldo.","Cocina cebolla y tomate; añade la carne y guisa jugosa.","Calienta los frijoles y cuece el arroz aparte.","Fríe plátano maduro y sirve los cuatro componentes juntos."]],ja:["パベジョン・クリオージョ（ベネズエラ風牛肉・豆・ご飯の盛り合わせ）",["牛肉をほぐれるまで煮て、煮汁を少し残します。","玉ねぎとトマトを炒め、ほぐした肉を加えて煮ます。","黒豆を温め、米は別に炊きます。","熟したプランテンを焼き、4品を並べて盛ります。"]],zh:["克里奥约拼盘（委内瑞拉牛肉黑豆饭）",["牛肉煮至可撕成丝，保留少量肉汤。","洋葱和番茄炒香，加入牛肉丝焖至多汁。","黑豆加热，大米另煮熟。","成熟大蕉片煎香，四部分并排装盘。"]]},
"ropa-vieja":{ko:["로파 비에하(쿠바식 찢은 쇠고기 스튜)",["쇠고기를 포크로 찢어질 만큼 부드럽게 삶고 살짝 식혀 찢습니다.","양파와 피망을 부드럽게 볶고 토마토와 쿠민을 넣습니다.","쇠고기와 육수를 조금 넣어 소스가 고기에 배도록 끓입니다.","얇게 썬 올리브를 섞고 간을 맞춰 밥과 냅니다."]],es:["Ropa vieja (guiso cubano de carne deshebrada)",["Cuece la carne hasta tierna, enfría un poco y deshebra.","Ablanda cebolla y pimiento; añade tomate y comino.","Devuelve la carne con un poco de caldo y reduce.","Incorpora aceitunas, sazona y sirve con arroz."]],ja:["ロパ・ビエハ（キューバ風ほぐし牛肉煮込み）",["牛肉を柔らかく煮て、少し冷まし細くほぐします。","玉ねぎとピーマンを炒め、トマトとクミンを加えます。","牛肉と煮汁少量を戻し、ソースが絡むまで煮ます。","オリーブを混ぜ、味を調えてご飯と出します。"]],zh:["旧衣牛肉丝（古巴番茄炖牛肉）",["牛肉煮至酥软，稍凉后撕成丝。","炒软洋葱和彩椒，加入番茄和孜然。","放回牛肉丝和少量肉汤，煮至酱汁挂肉。","拌入橄榄，调味后配米饭。"]]},
"hainanese-chicken-rice":{ko:["하이난 치킨라이스(싱가포르식 삶은 닭고기밥)",["생강을 넣은 육수에 닭고기를 완전히 익도록 부드럽게 삶아 덮어 둡니다.","씻은 쌀을 다진 마늘과 닭기름 또는 기름에 가볍게 볶습니다.","계량한 닭육수와 묶은 판단잎을 넣어 밥을 짓습니다.","닭을 썰어 향긋한 밥 위에 담고 뜨거운 육수를 곁들입니다."]],es:["Arroz con pollo de Hainan (pollo escalfado de Singapur)",["Escalfa el pollo con jengibre hasta cocerlo y déjalo reposar.","Sofríe el arroz lavado con ajo y grasa de pollo o aceite.","Cuece con caldo medido y una hoja de pandano anudada.","Corta el pollo y sírvelo sobre el arroz con caldo caliente."]],ja:["海南鶏飯（シンガポール風ゆで鶏ご飯）",["生姜入りスープで鶏肉を完全に火が通るまでゆで、休ませます。","洗った米をにんにくと鶏脂または油で軽く炒めます。","計量した鶏だしと結んだパンダン葉で炊きます。","鶏肉を切って香り米にのせ、温かいスープを添えます。"]],zh:["海南鸡饭（新加坡白切鸡油饭）",["鸡肉与姜片放鸡汤中小火浸煮至熟，盖好静置。","洗净大米与蒜末、鸡油或食用油略炒。","加入定量鸡汤和打结斑斓叶煮饭。","鸡肉切片铺在香饭上，配热汤食用。"]]},
"ful-medames":{ko:["풀 메담메스(이집트식 양념 누에콩)",["익힌 누에콩에 물 몇 숟갈을 넣어 매우 부드럽게 데웁니다.","식감이 남도록 콩 절반만 으깹니다.","으깬 마늘, 쿠민, 레몬즙, 올리브유를 섞습니다.","깍둑 썬 토마토를 올리고 소금과 산미를 맞춰 따뜻하게 냅니다."]],es:["Ful medames (habas egipcias sazonadas)",["Calienta las habas cocidas con unas cucharadas de agua.","Machaca solo la mitad para conservar textura.","Mezcla ajo, comino, limón y aceite de oliva.","Corona con tomate, ajusta sal y acidez y sirve tibio."]],ja:["フール・メダメス（エジプト風味付けそら豆）",["ゆでそら豆を少量の水と柔らかく温めます。","食感を残して半量だけつぶします。","にんにく、クミン、レモン汁、オリーブ油を混ぜます。","角切りトマトをのせ、塩と酸味を調えて温かく出します。"]],zh:["富尔豆泥（埃及调味蚕豆）",["熟蚕豆加几匙水加热至很软。","只压碎一半以保留口感。","拌入蒜泥、孜然、柠檬汁和橄榄油。","铺番茄丁，调整盐味和酸味后温热食用。"]]},
"kutia":{ko:["쿠티아(우크라이나식 밀·양귀비씨·꿀 푸딩)",["불린 통밀알을 새 물에 부드럽고 쫄깃하게 삶습니다.","양귀비씨를 뜨거운 물에 불려 물기를 빼고 향이 나도록 갑니다.","밀알에 양귀비씨, 꿀, 다진 호두, 건포도를 섞습니다.","따뜻한 물로 농도를 맞춰 맛이 어우러지게 둔 뒤 따뜻하거나 차게 냅니다."]],es:["Kutia (pudin ucraniano de trigo, amapola y miel)",["Cuece el trigo remojado hasta tierno y algo firme.","Remoja la amapola, escurre y muele hasta aromática.","Mezcla trigo, amapola, miel, nueces y pasas.","Aligera con agua tibia, deja reposar y sirve tibio o frío."]],ja:["クチャ（ウクライナ風小麦・けしの実・はちみつプディング）",["浸した小麦粒を柔らかく歯ごたえが残るまで煮ます。","けしの実を湯で戻し、水を切って香りが出るまですります。","小麦、けしの実、はちみつ、くるみ、レーズンを混ぜます。","温水で濃さを調え、なじませて温かくまたは冷やして出します。"]],zh:["库佳甜麦粥（乌克兰罂粟籽蜂蜜布丁）",["浸泡小麦粒换新水煮至软而有嚼劲。","罂粟籽热水泡软，沥干后研磨出香。","小麦拌罂粟籽、蜂蜜、核桃碎和葡萄干。","温水调浓稠度，静置入味后冷热皆可。"]]},
"soto-betawi":{ko:["소토 브타위(자카르타식 쇠고기 코코넛 수프)",["쇠고기를 생강과 물에 부드럽게 삶아 한입 크기로 썹니다.","감자를 따로 거의 익을 때까지 삶아 물기를 뺍니다.","거른 쇠고기 육수에 코코넛밀크를 넣어 세게 끓이지 않고 데웁니다.","고기와 감자를 넣고 토마토와 간을 더한 뒤 라임으로 마무리합니다."]],es:["Soto Betawi (sopa de Yakarta con ternera y coco)",["Cuece la carne con jengibre hasta tierna y córtala.","Cuece la patata aparte hasta casi tierna.","Añade leche de coco al caldo colado sin hervir fuerte.","Devuelve carne y patata, añade tomate y termina con lima."]],ja:["ソト・ブタウィ（ジャカルタ風牛肉ココナツスープ）",["牛肉を生姜と水で柔らかく煮て一口大に切ります。","じゃがいもは別にほぼ柔らかくゆでます。","こした牛だしにココナツミルクを加え、沸騰させず温めます。","肉といも、トマトを加え、味を調えライムで仕上げます。"]],zh:["巴达维牛肉汤（雅加达椰奶牛肉汤）",["牛肉与姜加水煮软，切成小块。","土豆另煮至近软并沥水。","过滤牛肉汤加入椰奶，避免猛烈沸腾。","放回牛肉和土豆，加番茄调味，最后挤青柠。"]]}
});
